import React, { useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom'; // React Router hooks
import { fetchItemById } from '../api'; // API function to fetch item by ID

const PlaceDetails = () => {
    const { id } = useParams(); // Get the id from URL params
    const navigate = useNavigate(); // To navigate programmatically

    const [place, setPlace] = useState(null); // Store place data
    const [loading, setLoading] = useState(false); // Track loading state
    const [error, setError] = useState(null); // Track error state

    const handleFetchPlace = async () => {
        setLoading(true); // Set loading state to true
        try {
            const data = await fetchItemById(id); // Fetch place by ID
            setPlace(data); // Store the place data
            setError(null); // Clear any previous errors
        } catch (error) {
            setError('Item not found or an error occurred while fetching data.'); // Set error message
            console.error('Error fetching item:', error);
        } finally {
            setLoading(false); // Set loading state to false
        }
    };

    // Only render details if the place is loaded
    if (loading) {
        return <div>Loading...</div>;
    }

    if (error) {
        return <div>{error}</div>;
    }

    return (
        <div className="place-details">
            <button onClick={handleFetchPlace}>Load Place</button> {/* Button to trigger fetch */}
            {place && (
                <div>
                    <img src={place.image} alt={place.location} className="place-details-img" />
                    <div className="place-hero">
                        <h2>{place.name}</h2>
                        <p><strong>About: </strong> {place.description}</p>
                        <p><strong>Max Visitors: </strong> {place.maxVisitors}</p>
                        <p><strong>Location: </strong> {place.location}</p>
                        <p className="price">Price: {place.price} UAH/day</p>
                        <div className="buttons">
                            <button onClick={() => navigate('/catalog')}>Return to catalog</button>
                            <button>Add to cart</button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default PlaceDetails;
